using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.ComponentModel;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Security.Cryptography;
namespace CircuitoStudio {
[DataContract]public enum FaultTraceKind{[EnumMember]Unknown,[EnumMember]InstantaneousSigned,[EnumMember]SymmetricRmsEnvelope}
[DataContract]public enum TraceInterpolation{[EnumMember]Linear,[EnumMember]LogLog}
[DataContract]public sealed class FaultTimeSample{[DataMember]public double TimeSeconds{get;set;}[DataMember]public double CurrentA{get;set;}public FaultTimeSample Copy(){return (FaultTimeSample)MemberwiseClone();}public void Validate(){Project.Range(TimeSeconds,0,1e6,"tempo do histórico");Project.Range(CurrentA,-1e12,1e12,"corrente do histórico");}}
[DataContract]public sealed class FaultTimeBinding {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Natureza da corrente (não confundir RMS/pico)")]public FaultTraceKind Kind{get;set;}[DataMember,DisplayName("Interpolação no domínio")]public TraceInterpolation Interpolation{get;set;}[DataMember,DisplayName("Frequência do caso (Hz)")]public double FrequencyHz{get;set;}[DataMember,DisplayName("Local / tipo de falta / fase medida")]public string FaultCase{get;set;}[DataMember,DisplayName("Equipamento / configuração exatos")]public string EquipmentReference{get;set;}[DataMember,DisplayName("Documento / página / fonte")]public string Reference{get;set;}[DataMember,DisplayName("Revisão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / pré-falta / limitações")]public string Conditions{get;set;}[DataMember,DisplayName("Método / resolução / erro de aquisição")]public string Acquisition{get;set;}[DataMember,DisplayName("SHA256 do documento original")]public string DocumentSha256{get;set;}[DataMember,DisplayName("FPcc declarado, opcional")]public double? DeclaredFaultPowerFactor{get;set;}[DataMember,DisplayName("Fonte / tempo do FPcc declarado")]public string PowerFactorReference{get;set;}[DataMember,Browsable(false)]public string ElectricalContext{get;set;}[DataMember,Browsable(false)]public string SamplesSha256{get;set;}[DataMember,Browsable(false)]public List<FaultTimeSample> Samples{get;set;}
public FaultTimeBinding(){Engine=FaultTimeTrace.EngineId;FaultCase=EquipmentReference=Reference=DataVersion=Conditions=Acquisition=DocumentSha256=PowerFactorReference=ElectricalContext=SamplesSha256="";Samples=new List<FaultTimeSample>();}public FaultTimeBinding Copy(){var c=(FaultTimeBinding)MemberwiseClone();c.Samples=Samples.Select(s=>s.Copy()).ToList();return c;}public void Validate(){if(Engine!=FaultTimeTrace.EngineId||!Enum.IsDefined(typeof(FaultTraceKind),Kind)||!Enum.IsDefined(typeof(TraceInterpolation),Interpolation))throw new InvalidDataException("Motor/natureza/interpolação do histórico desconhecidos.");Project.Range(FrequencyHz,1,1000,"frequência do histórico");if(DeclaredFaultPowerFactor.HasValue)Project.Range(DeclaredFaultPowerFactor.Value,0,1,"FPcc declarado");foreach(var s in new[]{FaultCase,EquipmentReference,Reference,DataVersion,Conditions,Acquisition,DocumentSha256,PowerFactorReference,ElectricalContext,SamplesSha256})ReturnSizing.Text(s,false);if(Samples==null||Samples.Count>50000||Samples.Any(s=>s==null))throw new InvalidDataException("Amostras ausentes/excessivas.");double previous=-1;foreach(var sample in Samples){sample.Validate();if(sample.TimeSeconds<=previous)throw new InvalidDataException("Tempos devem ser estritamente crescentes, sem duplicatas.");previous=sample.TimeSeconds;if(Kind==FaultTraceKind.SymmetricRmsEnvelope&&sample.CurrentA<0)throw new InvalidDataException("Envelope RMS não pode ser negativo.");if(Interpolation==TraceInterpolation.LogLog&&(sample.TimeSeconds<=0||sample.CurrentA<=0))throw new InvalidDataException("Log-log exige t/I positivos.");}if(Kind==FaultTraceKind.InstantaneousSigned&&Interpolation!=TraceInterpolation.Linear)throw new InvalidDataException("Amostras instantâneas usam interpolação linear.");}
}
public sealed class FaultTimeResult{public bool Accepted;public string Status,Detail;public double? ObservedInstantaneousPeakA,MinimumSymmetricRmsA,MaximumSymmetricRmsA,DeclaredFaultPowerFactor;public double StartSeconds,EndSeconds;}
public static class FaultTimeTrace {
public const string EngineId="cs-historico-curto-v1";public const string Header="TimeSeconds;CurrentA";
static string Hash(byte[] b){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLowerInvariant();}static string N(double x){return x.ToString("R",CultureInfo.InvariantCulture);}static bool Trace(string s){return !String.IsNullOrWhiteSpace(s)&&!s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase);}static bool IsHash(string s){return s!=null&&s.Length==64&&s.All(x=>Uri.IsHexDigit(x));}
static byte[] Serialize(object obj,Type type){using(var m=new MemoryStream()){new DataContractJsonSerializer(type).WriteObject(m,obj);return m.ToArray();}}
public static string Context(Project p,Circuit c){if(!p.Boards.Any(b=>b.Circuits.Contains(c)))throw new InvalidDataException("Circuito fora do projeto.");var data=new StringBuilder(Convert.ToBase64String(Serialize(p.Source,typeof(SourceSettings)))+"|"+N(p.Frequency)+"|"+c.Id);if(p.GroundingSource!=null)data.Append(Convert.ToBase64String(Serialize(p.GroundingSource,typeof(GroundingSource))));if(p.LoopSource!=null)data.Append(Convert.ToBase64String(Serialize(p.LoopSource,typeof(LoopSource))));foreach(var board in p.Boards){data.Append("|"+board.Id+"|"+board.SeparatesPEN);foreach(var wire in board.Circuits){data.Append("|"+FaultExtremes.Context(p,wire)+"|"+N(wire.PowerKw)+"|"+N(wire.DemandFactor)+"|"+N(wire.PowerFactor)+"|"+(wire.ReactiveKvarOverride.HasValue?N(wire.ReactiveKvarOverride.Value):"")+"|"+wire.PhaseLabel);if(wire.Conductors!=null)data.Append(Convert.ToBase64String(Serialize(wire.Conductors,typeof(CircuitConductors))));if(wire.ReturnSizing!=null)data.Append(Convert.ToBase64String(Serialize(wire.ReturnSizing,typeof(ReturnSizingBinding))));}}if(p.FaultExtremes!=null)data.Append("|"+Convert.ToBase64String(Serialize(p.FaultExtremes,typeof(FaultExtremeProfile))));return Hash(Encoding.UTF8.GetBytes(data.ToString()));}
public static string SamplesHash(IEnumerable<FaultTimeSample> samples){return Hash(Encoding.UTF8.GetBytes(String.Join("\n",samples.Select(s=>N(s.TimeSeconds)+";"+N(s.CurrentA)))));}
public static FaultTimeBinding Import(Project p,Circuit c,FaultTimeBinding metadata,string path){var copy=metadata.Copy();copy.Samples=ComponentCsv.Import<FaultTimeSample>(path,Header,x=>x.Validate(),x=>N(x.TimeSeconds));copy.ElectricalContext=Context(p,c);copy.SamplesSha256=SamplesHash(copy.Samples);copy.Validate();return copy;}
public static void ExportSamples(FaultTimeBinding data,string path){data.Validate();ComponentCsv.Export(data.Samples,path,Header,x=>x.Validate(),x=>N(x.TimeSeconds));}
public static FaultTimeResult Evaluate(Project p,Circuit c,FaultTimeBinding binding){var result=new FaultTimeResult();if(binding==null){result.Status="Histórico ausente";return result;}binding.Validate();string error=null;if(binding.Kind==FaultTraceKind.Unknown||binding.Samples.Count<2)error="Declare natureza e pelo menos duas amostras.";else if(binding.FrequencyHz!=p.Frequency)error="Frequência do histórico diverge do projeto.";else if(binding.ElectricalContext!=Context(p,c))error="Fonte/rede/caso elétrico alterados desde a importação.";else if(binding.SamplesSha256!=SamplesHash(binding.Samples))error="Amostras alteradas sem nova importação rastreável.";else if(!IsHash(binding.DocumentSha256)||!new[]{binding.FaultCase,binding.EquipmentReference,binding.Reference,binding.DataVersion,binding.Conditions,binding.Acquisition}.All(Trace))error="Rastreabilidade do documento/caso/aquisição incompleta.";else if(binding.DeclaredFaultPowerFactor.HasValue&&!Trace(binding.PowerFactorReference))error="FPcc declarado exige fonte/tempo de aplicação.";if(error!=null){result.Status="Dados incompletos/incompatíveis";result.Detail=error;return result;}result.Accepted=true;result.Status="Histórico importado válido no domínio documentado";result.StartSeconds=binding.Samples.First().TimeSeconds;result.EndSeconds=binding.Samples.Last().TimeSeconds;result.DeclaredFaultPowerFactor=binding.DeclaredFaultPowerFactor;if(binding.Kind==FaultTraceKind.InstantaneousSigned)result.ObservedInstantaneousPeakA=binding.Samples.Max(x=>Math.Abs(x.CurrentA));else{result.MinimumSymmetricRmsA=binding.Samples.Min(x=>x.CurrentA);result.MaximumSymmetricRmsA=binding.Samples.Max(x=>x.CurrentA);}result.Detail="Caso "+binding.FaultCase+"; equipamento "+binding.EquipmentReference+"; "+binding.Reference+" / "+binding.DataVersion+"; "+binding.Conditions+"; aquisição "+binding.Acquisition+". Interpolação "+binding.Interpolation+" entre "+N(result.StartSeconds)+" e "+N(result.EndSeconds)+" s. "+(binding.Kind==FaultTraceKind.InstantaneousSigned?"Pico observado nas amostras/polilinha; resolução pode omitir pico real. Não é limite superior garantido.":"Envelope AC simétrico RMS: não fornece pico instantâneo/assimétrico, componente DC ou FPcc calculado. Não sintetiza onda R-L de máquina.")+" Sem extrapolação, tempo de desligamento ou aprovação de proteção; hash não autentica fabricante.";return result;}
public static double At(Project p,Circuit c,FaultTimeBinding b,double seconds){Project.Range(seconds,0,1e6,"tempo de consulta");var result=Evaluate(p,c,b);if(!result.Accepted||seconds<result.StartSeconds||seconds>result.EndSeconds)throw new InvalidDataException("Consulta fora do domínio/sem histórico aceito.");int index=b.Samples.FindIndex(x=>x.TimeSeconds>=seconds);var end=b.Samples[index];if(index==0||end.TimeSeconds==seconds)return end.CurrentA;var start=b.Samples[index-1];if(b.Interpolation==TraceInterpolation.Linear)return start.CurrentA+(end.CurrentA-start.CurrentA)*(seconds-start.TimeSeconds)/(end.TimeSeconds-start.TimeSeconds);return Math.Exp(Math.Log(start.CurrentA)+(Math.Log(end.CurrentA)-Math.Log(start.CurrentA))*(Math.Log(seconds)-Math.Log(start.TimeSeconds))/(Math.Log(end.TimeSeconds)-Math.Log(start.TimeSeconds)));}
public static void AppendReport(Project p,Circuit c,StringBuilder text){if(c.FaultTimeTrace==null)return;var r=Evaluate(p,c,c.FaultTimeTrace);text.AppendLine("HISTÓRICO TEMPORAL IMPORTADO — "+EngineId);text.AppendLine(r.Status+". "+r.Detail);if(!r.Accepted)return;var b=c.FaultTimeTrace;text.AppendLine("Natureza="+b.Kind+"; amostras="+b.Samples.Count+"; SHA256doc="+b.DocumentSha256+"; SHA256amostras="+b.SamplesSha256);text.AppendLine("Pico instantâneo observado(A)="+(r.ObservedInstantaneousPeakA.HasValue?N(r.ObservedInstantaneousPeakA.Value):"não fornecido por envelope RMS")+"; mínimo/máximo AC RMS(A)="+(r.MinimumSymmetricRmsA.HasValue?N(r.MinimumSymmetricRmsA.Value)+" / "+N(r.MaximumSymmetricRmsA.Value):"não deduzido de amostras instantâneas")+"; FPcc declarado="+(r.DeclaredFaultPowerFactor.HasValue?N(r.DeclaredFaultPowerFactor.Value)+"; "+b.PowerFactorReference:"desconhecido"));}
}
public sealed partial class Circuit{[DataMember,Browsable(false)]public FaultTimeBinding FaultTimeTrace{get;set;}}
}
